\-- Create initial tables for posokanei replica CREATE TABLE supermarkets ( id UUID PRIMARY KEY DEFAULT gen\_random\_uuid(), name TEXT NOT NULL UNIQUE, logo\_url TEXT, is\_active BOOLEAN DEFAULT true, created\_at TIMESTAMPTZ DEFAULT NOW() ); CREATE TABLE categories ( id UUID PRIMARY KEY DEFAULT gen\_random\_uuid(), parent\_id UUID REFERENCES categories(id) ON DELETE SET NULL, name\_el TEXT NOT NULL, slug TEXT UNIQUE NOT NULL ); CREATE TABLE products ( id UUID PRIMARY KEY DEFAULT gen\_random\_uuid(), ean TEXT UNIQUE NOT NULL, name\_el TEXT NOT NULL, brand TEXT, category\_id UUID REFERENCES categories(id), unit\_type TEXT NOT NULL, package\_quantity NUMERIC(10,2), created\_at TIMESTAMPTZ DEFAULT NOW() ); CREATE TABLE daily\_prices ( id UUID PRIMARY KEY DEFAULT gen\_random\_uuid(), product\_id UUID REFERENCES products(id) ON DELETE CASCADE, supermarket\_id UUID REFERENCES supermarkets(id) ON DELETE CASCADE, price NUMERIC(10,2) NOT NULL, price\_per\_unit NUMERIC(10,2) NOT NULL, is\_offer BOOLEAN DEFAULT false, date DATE NOT NULL, CONSTRAINT unique\_product\_store\_date UNIQUE (product\_id, supermarket\_id, date) ); CREATE INDEX idx\_daily\_prices\_lookup ON daily\_prices (date, product\_id);